code.en:
#!/bin/bash
echo -n "Enter two numbers: "
read a b
echo "1.Add 2.Subtract 3.Multiply 4.Divide"
echo -n "Enter choice: "
read ch
case $ch in
  1) echo "Sum = $((a + b))" ;;
  2) echo "Difference = $((a - b))" ;;
  3) echo "Product = $((a * b))" ;;
  4) if [ $b -eq 0 ]; then
       echo "Cannot divide by zero"
     else
       echo "Quotient = $((a / b))"
     fi ;;
  *) echo "Invalid choice" ;;
esac

