code.en:
#!/bin/bash
echo -n "Enter a character: "
read c
case $c in
  [aeiouAEIOU]) echo "$c is a vowel" ;;
  [a-zA-Z]) echo "$c is a consonant" ;;
  [0-9]) echo "$c is a digit" ;;
  *) echo "$c is a special symbol" ;;
esac

